from pathlib import Path

path = Path("index.html")
source = path.read_text(encoding="utf-8")

if ".hero-flow{" not in source:
    source = source.replace(
        ".dark .tag{background:rgba(255,255,255,.09);border-color:rgba(255,255,255,.16);color:#fff}.foot",
        ".dark .tag{background:rgba(255,255,255,.09);border-color:rgba(255,255,255,.16);color:#fff}.hero-flow{display:flex;align-items:center;justify-content:center;gap:18px;text-align:center;max-width:100%}.hero-node{min-width:0}.hero-emoji{font-size:3.5rem;line-height:1.1}.hero-node:nth-of-type(2) .hero-emoji{font-size:4rem}.hero-arrow{font-size:2rem;line-height:1}.foot",
    )

old_media = """@media(max-width:900px){.stage{padding:10px;align-items:start}.deck{aspect-ratio:auto;min-height:calc(100vh - 150px);border-radius:15px}.slide{padding:27px 22px;overflow-y:auto}.two,.three,.four{grid-template-columns:1fr}.flow{grid-template-columns:repeat(2,1fr)}.arch{grid-template-columns:1fr}.arr{transform:rotate(90deg);min-height:32px}.box{min-height:auto}.timeline{grid-template-columns:1fr}.panel{min-height:230px}.brand small{display:none}}
@media(max-width:560px){.bar{padding-inline:11px}.brand b{font-size:.82rem}.btn span,.nav span{display:none}.stage{padding:7px}.deck{min-height:calc(100vh - 137px)}.slide{padding:23px 17px}.card{padding:14px}.four,.three{gap:9px}.status{flex:1 1 42%;max-width:none;min-width:0}.arrow{display:none}.controls{height:64px;padding-inline:9px;gap:7px}.counter{min-width:54px;font-size:.72rem}.ask{grid-template-columns:1fr}}"""

new_media = """@media(max-width:899.98px){
html,body{height:100%;overflow:hidden;overscroll-behavior:none}.app{height:100svh;height:100dvh;min-height:0;grid-template-rows:auto minmax(0,1fr) auto;overflow:hidden}.bar{position:relative;height:auto;min-height:64px;padding:calc(8px + env(safe-area-inset-top,0px)) 12px 8px}.brand{gap:11px}.logo{width:44px;height:44px;flex:0 0 44px}.brand b{font-size:.94rem}.brand small{display:none}.btn,.nav{min-width:48px;min-height:48px;display:inline-grid;place-items:center}.stage{min-height:0;padding:8px;display:block;overflow:hidden}.deck{width:100%;height:100%;min-height:0;aspect-ratio:auto;border-radius:18px;overflow:hidden}.slide{display:block;position:absolute;inset:0;min-width:0;padding:clamp(22px,5.5vw,38px) clamp(17px,5vw,34px) calc(34px + env(safe-area-inset-bottom,0px));overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;touch-action:pan-y;-webkit-overflow-scrolling:touch;scrollbar-gutter:stable;transform:translateX(5%)}.slide.active{transform:none}.head{display:block;min-width:0}.head>div{min-width:0}.num{display:none}h1{font-size:clamp(2.15rem,10.8vw,3.7rem);line-height:.98;letter-spacing:-.048em}h2{font-size:clamp(1.78rem,8.2vw,3rem);line-height:1.04;letter-spacing:-.038em}h3{font-size:clamp(1rem,4.7vw,1.32rem)}.lead{font-size:clamp(.98rem,4.1vw,1.16rem);line-height:1.55}.eyebrow{font-size:.72rem;line-height:1.3}.content{display:block!important;min-height:0;margin-top:28px;align-content:initial}.content>*+*{margin-top:16px}.two,.three,.four,.timeline,.arch{display:grid!important;grid-template-columns:minmax(0,1fr)!important;align-items:stretch!important;gap:14px!important}.card,.phase,.ask,.panel,.box,.metric,.status{max-width:100%;min-width:0}.card{padding:18px}.panel{min-height:0;padding:18px}.metrics{height:auto;grid-template-columns:repeat(2,minmax(0,1fr));align-content:start;gap:10px}.metric{padding:15px}.list{margin-top:18px;gap:14px}.item{font-size:.98rem;line-height:1.48}.flow{display:grid;grid-template-columns:1fr;gap:0}.step{display:grid;grid-template-columns:54px minmax(0,1fr);grid-template-areas:\"circle title\" \"circle copy\";column-gap:14px;row-gap:3px;text-align:left;padding:12px 0;border-bottom:1px solid var(--line)}.dark .step{border-color:rgba(255,255,255,.15)}.step:last-child{border-bottom:0}.circle{grid-area:circle;width:48px;height:48px;margin:0;align-self:center}.step b{grid-area:title;align-self:end;font-size:.96rem}.step small{grid-area:copy;font-size:.78rem;line-height:1.35}.pipe{display:grid;grid-template-columns:minmax(0,1fr);gap:7px}.status{width:100%;max-width:none;padding:14px 16px;font-size:.82rem}.arrow{display:block;height:18px;line-height:18px;text-align:center;transform:rotate(90deg)}.arch{gap:8px!important}.arr{min-height:26px;transform:rotate(90deg);font-size:1.45rem}.box{min-height:0;padding:20px}.box ul{font-size:.84rem;line-height:1.4}.shield{width:min(210px,66vw);margin-top:20px}.ask{grid-template-columns:48px minmax(0,1fr);padding:17px;gap:14px}.ask+.ask{margin-top:11px}.askn{width:46px;height:46px}.hero-flow{flex-direction:column;gap:10px}.hero-node{width:100%;padding:15px 12px;border-radius:16px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12)}.hero-arrow{transform:rotate(90deg);font-size:1.55rem}.hero-emoji,.hero-node:nth-of-type(2) .hero-emoji{font-size:3rem}.tags{gap:8px;margin-top:18px}.tag{white-space:normal;text-align:center;line-height:1.25}.foot{display:grid;grid-template-columns:1fr;gap:6px;margin-top:28px;padding-top:18px;border-top:1px solid var(--line);font-size:.75rem;line-height:1.4}.dark .foot{border-color:rgba(255,255,255,.15)}.foot b{justify-self:start}.controls{position:relative;height:auto;min-height:72px;padding:8px 10px calc(8px + env(safe-area-inset-bottom,0px));grid-template-columns:54px minmax(0,1fr) auto;gap:8px}.counter{min-width:0;font-size:.76rem}.progress{height:5px}.dots{gap:5px;margin-top:7px}.dot{width:8px;height:8px;min-width:8px}.dot.on{width:24px}.navs{gap:7px}.nav{padding:0 13px}.slide img,.slide svg,.slide video,.slide canvas{max-width:100%;height:auto}}
@media(max-width:560px){.bar{padding-inline:10px}.brand b{font-size:.84rem}.btn span,.nav span{display:none}.stage{padding:6px}.deck{border-radius:15px}.slide{padding:22px 16px calc(30px + env(safe-area-inset-bottom,0px))}h1{font-size:clamp(2.05rem,11.8vw,2.85rem)}h2{font-size:clamp(1.7rem,9vw,2.35rem)}.card{padding:15px}.metrics{grid-template-columns:1fr}.ask{grid-template-columns:1fr}.askn{width:44px;height:44px}.controls{grid-template-columns:48px minmax(0,1fr) auto;padding-inline:8px}.counter{font-size:.7rem}.nav{min-width:48px;padding:0}.hero-node{padding:13px 10px}}
@media(max-height:650px) and (max-width:899.98px){.bar{min-height:56px}.logo{width:38px;height:38px;flex-basis:38px}.slide{padding-top:18px}.controls{min-height:64px}.btn,.nav{min-height:44px;min-width:44px}}"""

if old_media in source:
    source = source.replace(old_media, new_media)
elif "@media(max-width:899.98px)" not in source:
    raise RuntimeError("Could not locate the original mobile media queries")

old_hero = """<div class=\"panel\" style=\"background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.14);display:grid;place-items:center\"><div style=\"display:flex;align-items:center;gap:18px;text-align:center\"><div><div style=\"font-size:3.5rem\">👤</div><b>Citizen</b></div><div style=\"font-size:2rem\">→</div><div><div style=\"font-size:4rem\">📱</div><b>Secure platform</b></div><div style=\"font-size:2rem\">→</div><div><div style=\"font-size:3.5rem\">🏛️</div><b>LGU officer</b></div></div></div>"""
new_hero = """<div class=\"panel\" style=\"background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.14);display:grid;place-items:center\"><div class=\"hero-flow\" aria-label=\"Citizen information flows through the secure platform to an LGU officer\"><div class=\"hero-node\"><div class=\"hero-emoji\" aria-hidden=\"true\">👤</div><b>Citizen</b></div><div class=\"hero-arrow\" aria-hidden=\"true\">→</div><div class=\"hero-node\"><div class=\"hero-emoji\" aria-hidden=\"true\">📱</div><b>Secure platform</b></div><div class=\"hero-arrow\" aria-hidden=\"true\">→</div><div class=\"hero-node\"><div class=\"hero-emoji\" aria-hidden=\"true\">🏛️</div><b>LGU officer</b></div></div></div>"""
if old_hero in source:
    source = source.replace(old_hero, new_hero)
elif 'class="hero-flow"' not in source:
    raise RuntimeError("Could not locate the original hero diagram")

script_start = source.index("(()=>{const slides=")
script_end = source.index("})();", script_start) + 5
new_script = """(()=>{const slides=[...document.querySelectorAll('.slide')],dots=document.getElementById('dots'),counter=document.getElementById('counter'),bar=document.getElementById('bar'),prev=document.getElementById('prev'),next=document.getElementById('next'),deck=document.getElementById('deck');let at=0,sx=0,sy=0,swipeReady=false;const pad=n=>String(n).padStart(2,'0'),interactive='button,a,input,textarea,select,label,[role=\"button\"]';slides.forEach((s,i)=>{const b=document.createElement('button');b.className='dot';b.type='button';b.ariaLabel=`Go to slide ${i+1}: ${s.dataset.title}`;b.onclick=()=>show(i);dots.appendChild(b)});const ds=[...dots.children];function show(i,hash=true){at=(i+slides.length)%slides.length;slides.forEach((s,n)=>{const active=n===at;s.classList.toggle('active',active);s.setAttribute('aria-hidden',String(!active));if(active)s.scrollTop=0});ds.forEach((d,n)=>{const active=n===at;d.classList.toggle('on',active);d.setAttribute('aria-current',active?'step':'false')});counter.textContent=`${pad(at+1)} / ${pad(slides.length)}`;bar.style.width=`${(at+1)/slides.length*100}%`;prev.disabled=at===0;prev.setAttribute('aria-disabled',String(at===0));next.innerHTML=at===slides.length-1?'<span>Start</span> ↺':'<span>Next</span> →';document.title=`${pad(at+1)} · ${slides[at].dataset.title} — Panabo Digital Permit Pilot`;if(hash)history.replaceState(null,'',`#slide-${at+1}`)}prev.onclick=()=>at&&show(at-1);next.onclick=()=>show(at===slides.length-1?0:at+1);document.getElementById('print').onclick=()=>print();document.onkeydown=e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(at===slides.length-1?0:at+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();if(at)show(at-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1)};deck.addEventListener('touchstart',e=>{swipeReady=e.touches.length===1&&!e.target.closest(interactive);if(!swipeReady)return;sx=e.touches[0].clientX;sy=e.touches[0].clientY},{passive:true});deck.addEventListener('touchend',e=>{if(!swipeReady||e.changedTouches.length!==1)return;swipeReady=false;const x=e.changedTouches[0].clientX-sx,y=e.changedTouches[0].clientY-sy;if(Math.abs(x)>=55&&Math.abs(x)>Math.abs(y)*1.35){if(x<0&&at<slides.length-1)show(at+1);if(x>0&&at>0)show(at-1)}},{passive:true});deck.addEventListener('touchcancel',()=>{swipeReady=false},{passive:true});const m=location.hash.match(/slide-(\\d+)/);show(m?Math.min(Math.max(+m[1]-1,0),slides.length-1):0,false)})();"""
source = source[:script_start] + new_script + source[script_end:]

path.write_text(source, encoding="utf-8")
print("Applied mobile swipe presentation fix")
